#!/usr/bin/env python3
"""Russia flagship course data, part 2: RU-09 to RU-16. Own wording; no brand, person or school names; no fees."""

C09 = dict(
 id='RU-09', title='Transportation', level='L4 Practitioner',
 summary='Plan, cost and run safe road freight and passenger-style transport jobs: routes, vehicle checks, driver hours, load security, trip costing and delivery records.',
 outcomes=[
  ('Understand', 'Explain how a trip is planned from order to proof of delivery and which records each step produces.'),
  ('Apply', 'Calculate trip distance, fuel use, driver time and cost per kilometre for a given route and vehicle.'),
  ('Analyse', 'Compare route and load options and identify the cheapest option that still meets the delivery window and safety limits.'),
  ('Evaluate', 'Judge a vehicle, driver and load for legal and safe departure using a written checklist.'),
  ('Create', 'Build a one-week dispatch plan with costing, compliance records and an incident response sheet.')],
 task='Prepare and cost a one-week dispatch plan for three vehicles and eight deliveries, with pre-trip checks, driver hours and delivery records.',
 condition='Desk exercise with a route table, vehicle data sheet, load list and spreadsheet; 4 hours; no live driving.',
 standard='Costs within 3 percent of the model figure, no driver-hours breach, every load has a securing note, and at least 90 percent of rubric points met.',
 who='Dispatchers, small fleet owners, new drivers who want to plan, and anyone moving into logistics coordination.',
 req='Basic arithmetic and spreadsheet use. A driving licence is not needed for the course but is needed to drive in real life.',
 safety='Road transport is regulated. Carrying goods or passengers for hire, dangerous goods, driver hours, vehicle inspection and insurance are all governed by the relevant federal rules and the competent Russian authority. This course teaches planning and records, not legal advice. Check with the competent Russian authority and a local adviser before you start operating, and never plan a trip that breaks driver-hours, weight or load-securing limits.',
 evidence='Evidence: costed trip sheets, a pre-trip checklist, a driver-hours log, a load securing note, a delivery record and an incident sheet.',
 modules=[
  ('How a trip flows', 'Understand', 3,
   'Every trip is a chain: order, plan, check, load, drive, deliver, record. A gap in the chain is where late, damaged or disputed deliveries come from.',
   ['Name the seven steps and the record each one leaves behind.', 'Separate the order (what, where, when) from the plan (which vehicle, which driver, which route).', 'Explain why proof of delivery protects both carrier and customer.', 'Show where hand-offs happen and who signs.'],
   'Order: 1,200 kg of packaged goods from depot to a shop 180 km away, window 08:00 to 12:00. Plan: 3.5 t van, depart 05:30. Records: order, checklist, load note, delivery note signed at 09:40.',
   'Draw the seven-step chain for one real or invented delivery and list the record at each step.',
   'All seven steps present, each with a named record and a named owner.'),
  ('Routes, distance and time', 'Apply', 4,
   'A route is judged on distance, time, road type and risk, not on distance alone. Time includes loading, rest and unloading.',
   ['Use average speeds by road type to estimate driving time, then add stops.', 'Add a buffer of 10 to 15 percent for weather and queues.', 'Plan return legs so the vehicle is not empty where possible.', 'Check bridge, weight and access limits on the route before departure.'],
   'Route 180 km: 120 km at 80 km/h = 1.5 h, 60 km at 50 km/h = 1.2 h, total 2.7 h. Add 15 percent buffer = 3.1 h. Add 45 min load and 30 min unload = 4.35 h door to door.',
   'Plan three routes of different length from one depot and compute door-to-door time for each.',
   'Times within 10 minutes of the model and a buffer shown on each route.'),
  ('Vehicle checks and upkeep', 'Evaluate', 4,
   'An unsafe vehicle is a legal and human risk. A short, written daily check finds most faults before they become failures.',
   ['Build a walk-round list: tyres, lights, brakes, fluids, mirrors, load area, documents.', 'Define which faults stop the trip and which can be reported for repair.', 'Keep a service schedule by kilometres and by date.', 'Record every defect, who found it and when it was fixed.'],
   'Van with service due every 15,000 km. Odometer 87,400 km, last service at 75,000 km: 12,400 km driven, 2,600 km left. At 400 km a week the service is due in 6.5 weeks, so book it in week 5.',
   'Write a one-page pre-trip checklist and run it against a sample fault report; mark go or no-go.',
   'Every no-go fault is caught and the service due date is correct to within 1 week.'),
  ('Driver hours and fatigue', 'Apply', 3,
   'Tired drivers cause crashes. Driving and rest limits exist in federal rules and must shape the schedule, not be fixed afterwards.',
   ['Check the current driving, break and rest limits with the competent authority and write them on the plan.', 'Build breaks into the schedule, not into the buffer.', 'Keep a simple log: start, breaks, end, kilometres.', 'Refuse a plan that needs the driver over the limit; split the trip or add a driver.'],
   'Planned day: 9 h of driving would exceed a 9 h daily limit once loading is added to duty time. Option: split into two days or relay with a second driver at the 5 h point, giving 4.5 h each.',
   'Take an 11-hour driving plan and rebuild it so each driver stays inside the limit you have confirmed.',
   'No driver over the confirmed limit and breaks are shown in the schedule.'),
  ('Load planning and securing', 'Apply', 3,
   'Weight limits and load securing are about stability and axle load. A load that moves in braking is a danger to everyone.',
   ['Check payload against the vehicle rating, never the gross figure alone.', 'Place heavy items low and forward; spread weight across the floor.', 'Use straps, blocking and anti-slip mats and note the number of tie-downs.', 'Photograph the secured load before departure.'],
   'Payload rating 1,500 kg. Load: 24 crates of 38 kg = 912 kg plus 6 drums of 55 kg = 330 kg; total 1,242 kg, margin 258 kg (17 percent). Use 6 straps, 4 over the crates and 2 over the drums.',
   'Plan the load for a given list of items, show total weight and margin, and write a securing note.',
   'Total within payload, heavy items low and a securing method noted for each group.'),
  ('Costing a trip', 'Analyse', 4,
   'Price must cover fuel, driver, vehicle wear, insurance, tolls, overhead and a margin for risk. Cost per kilometre is the base number.',
   ['Split costs into fixed (per month) and variable (per kilometre).', 'Calculate fuel from consumption per 100 km and the pump price.', 'Add driver time, wear and tolls, then overhead.', 'Compare the quote with cost and find the break-even load.'],
   'Trip 180 km one way, 360 km return. Fuel 12 L per 100 km x 360 = 43.2 L at 62 RUB = 2,678 RUB. Driver 10 h at 350 RUB = 3,500 RUB. Wear 6 RUB/km x 360 = 2,160 RUB. Tolls 400 RUB. Total variable 8,738 RUB; cost per km 24.3 RUB.',
   'Cost three trips and set a quote for each with a 12 percent margin.',
   'Each total within 3 percent of the model and the margin shown separately.'),
  ('Compliance, insurance and incidents', 'Evaluate', 3,
   'Operating for hire needs the right permissions, documents and insurance. When something goes wrong, calm and record keeping decide the outcome.',
   ['List the documents that travel with the vehicle and driver and who checks them.', 'Ask the competent authority and an adviser which permit applies to your kind of transport.', 'Write a three-step incident sheet: make safe, call, record.', 'Photograph, note witnesses and keep the load documents.'],
   'Minor collision, no injury: stop, hazard lights, call the emergency service if needed, photograph 6 views, note the time and place, inform the dispatcher within 15 minutes and the insurer the same day.',
   'Write an incident sheet and a document checklist for your own planned operation.',
   'Sheet has make-safe, call and record steps; checklist names a checker for each document.'),
  ('Dispatch plan and review', 'Create', 4,
   'Bring it together: a week of work with cost, compliance and a review of what went wrong.',
   ['Allocate vehicles and drivers to jobs by capacity, location and hours.', 'Attach checklist, load note and cost to each trip.', 'Track on-time delivery and cost per kilometre.', 'Hold a weekly review and change one thing.'],
   'Week: 8 deliveries, 3 vehicles, 1,920 km, total cost 46,700 RUB = 24.3 RUB/km. 7 of 8 on time = 87.5 percent. Change: start the late route 30 minutes earlier.',
   'Build the full one-week dispatch plan from the data pack.',
   'Plan passes all checks above and the review names one measurable change.')],
 quiz=[
  ('Name the seven steps of a trip.', 'Order, plan, check, load, drive, deliver, record.'),
  ('Why add a buffer to the driving time?', 'Weather, queues and stops are normal; a 10 to 15 percent buffer keeps the delivery window realistic.'),
  ('A vehicle has a payload of 1,500 kg and a load of 1,242 kg. What is the margin?', '258 kg, about 17 percent.'),
  ('Who decides the driver-hours limit you plan to?', 'The relevant federal rules and the competent authority; confirm the current figures before planning.'),
  ('What is the first step after a minor collision?', 'Make the scene safe, then call for help if needed and record.'),
  ('Fuel 12 L/100 km over 360 km at 62 RUB per litre costs what?', '43.2 L x 62 = 2,678 RUB (rounded).'),
  ('Why photograph a secured load?', 'It is evidence the load was secured at departure.'),
  ('What is the difference between fixed and variable cost?', 'Fixed cost is per month whatever you drive; variable cost rises with kilometres.'),
  ('A pre-trip check finds a brake fault. Go or no-go?', 'No-go until repaired and re-checked.'),
  ('What does proof of delivery protect?', 'Both carrier and customer against disputes about time, quantity and condition.')],
 rubric=[
  ('Planning', 'Chain incomplete or no owners.', 'All steps, records and owners shown.', 'Also shows contingency routes and alternates.'),
  ('Costing', 'Totals more than 3 percent off or margin missing.', 'Within 3 percent, margin shown.', 'Also shows break-even load and sensitivity to fuel price.'),
  ('Compliance', 'Hours or weight limit broken.', 'No breach; limits confirmed with a source.', 'Also gives an audit-ready record set.'),
  ('Safety', 'No securing or check note.', 'Checks and securing noted for each trip.', 'Also analyses near-miss patterns.'),
  ('Review', 'No measure used.', 'On-time rate and cost per km tracked.', 'Also tests a change and reports the effect.')],
 ladder=[
  'L1 Basic: Remember the steps of a trip and why a delivery record matters.',
  'L2 Awareness: Describe the main safety and legal duties around a road trip (check the current rules).',
  'L3 Foundation: Calculate trip time and fuel for one simple route.',
  'L4 Practitioner: Plan, cost and document a week of trips for a small fleet.',
  'L5 Specialist: Analyse fleet cost per kilometre and redesign routes to cut empty running.',
  'L6 Advanced: Design a compliance and maintenance system for a mixed fleet.',
  'L7 Super expert: Create a network-level transport strategy and train dispatch teams (needs years of practice).'],
 jobs=[('Dispatcher', 'Plans trips, allocates drivers and keeps delivery records.'), ('Fleet coordinator', 'Tracks maintenance, documents and costs for a small fleet.'), ('Transport planner', 'Designs routes and schedules to meet service windows at lowest cost.'), ('Owner-driver (with the right permits)', 'Runs one vehicle as a small business and keeps own compliance records.'), ('Warehouse and loading supervisor', 'Plans and checks load securing and hand-offs.')],
 next='Related generic courses: Logistics and Warehousing, Vehicle Maintenance, Small Business Bookkeeping.')

C10 = dict(
 id='RU-10', title='Language Translation', level='L4 Practitioner',
 summary='Translate and revise practical texts between two languages with accurate meaning, consistent terms, quality checks, confidentiality and a clear quote and delivery process.',
 outcomes=[
  ('Understand', 'Explain the difference between literal, faithful and adapted translation and when each is right.'),
  ('Apply', 'Translate a 500-word practical text with consistent terminology and correct numbers, dates and units.'),
  ('Analyse', 'Compare a draft with its source and classify errors by type and severity.'),
  ('Evaluate', 'Judge machine output and decide what must be corrected by a human before delivery.'),
  ('Create', 'Build a glossary, quote and delivery pack for a small client job.')],
 task='Translate and revise a 500-word practical text, build a 20-term glossary and deliver it with a quote and a quality note.',
 condition='Desk exercise with a source text, style notes and a spreadsheet; 4 hours; any dictionary or software tools you can use legally.',
 standard='No meaning error in numbers or names, at most 2 minor style errors per 500 words, glossary used consistently, and at least 90 percent of rubric points.',
 who='Bilingual people starting paid translation work, office staff who translate and students of languages.',
 req='Strong reading ability in the source language and writing ability in the target language.',
 safety='Some translations carry legal weight (for example documents for courts or official use): certification, sworn status and notarial rules are set by the relevant federal rules and the competent authority. Do not claim a status you do not hold. Medical, legal and technical texts need subject checks. Respect client confidentiality and copyright, and do not upload private client text to services you have not checked. Check with the competent Russian authority and a local adviser about certified work.',
 evidence='Evidence: the translation, a glossary, an error log, a quote and a delivery note with a quality statement.',
 modules=[
  ('What translation is', 'Understand', 3,
   'Translation carries meaning, tone and purpose across languages. The brief decides how close to the words you stay. Decide this before the first word is written, because a wrong choice affects every sentence and costs a full rewrite if it is found late in the job.',
   ['Define source and target text, purpose and reader.', 'Contrast literal, faithful and adapted styles with one example each.', 'List what must never change: names, numbers, dates, units.', 'Ask the client five brief questions before you start.'],
   'Source sentence on a leaflet: a figure of 2.5 cm. In the target readers expect millimetres, so the brief decides: keep 2.5 cm or write 25 mm. The decision goes on the style sheet. Check: the sheet now records the unit rule, so all 9 other measurements in the leaflet follow the same choice without new debate.',
   'Write a brief of five questions and answer them for a sample job.',
   'Brief states purpose, reader, tone, format and deadline.'),
  ('Reading the source', 'Analyse', 3,
   'Most errors start in misreading. Read for the argument, the terms and the traps before translating. Spend about one tenth of the job time on this pass; it is the cheapest quality step because a misread idea repeats in every later sentence.',
   ['Read the whole text once without translating.', 'Mark terms, idioms, names and numbers.', 'Flag ambiguous passages and ask the client.', 'Count the words to price and plan the job.'],
   'Text of 500 words, 12 terms marked, 5 idioms, 9 numbers. Planned speed 350 words per hour: draft 1.4 h, revision 0.7 h, total 2.1 h. Check: 12 + 5 + 9 = 26 marked items, about one per 19 words, so allow extra time for client queries.',
   'Mark up a 300-word sample and list the five biggest risks.',
   'All numbers and names marked and risks ranked.'),
  ('Drafting', 'Apply', 4,
   'Write natural target-language sentences that keep the meaning. Do not translate word by word. Good drafts come from reading a sentence, setting its shape aside, and then writing the idea as a native reader would say it.',
   ['Restructure sentences to fit target-language order.', 'Convert units and formats only as the style sheet says.', 'Keep terms consistent across the text.', 'Leave a query note instead of guessing.'],
   'Source date 03/04/2025 may mean 3 April or 4 March. Ask the client. If the answer is 3 April, write it as 3 April 2025 to avoid doubt. Check: one query sent before drafting costs about 2 minutes, while a wrong date found after delivery costs a corrected file and possibly the client.',
   'Translate a 300-word text and annotate 5 decisions.',
   'No meaning errors in numbers or names and 5 decisions justified.'),
  ('Terminology and glossaries', 'Create', 3,
   'A glossary makes a long job or a repeat client consistent and saves time. Build it while drafting, not after, so each choice is recorded once and reused instead of being rediscovered at every repeat.',
   ['Collect terms with the chosen equivalent, source of the choice and note.', 'Check terms in reliable references and client material.', 'Keep one term per concept.', 'Share the glossary with the client for approval.'],
   'Glossary of 20 terms: 14 from the client, 6 chosen by you with a reference. In a 500-word text 11 of the terms occur a total of 37 times; consistent use gives 37 of 37. Check: 14 + 6 = 20 terms, and 37 of 37 matches means a consistency rate of 100 percent; one slip would give 36 of 37, about 97 percent.',
   'Build a 20-term glossary from a sample text and apply it.',
   'No term used two ways and each choice has a source.'),
  ('Revision and quality checks', 'Evaluate', 4,
   'Revise in two passes: against the source for accuracy, then alone for reading quality. Count errors. The two passes use different attention, which is why doing both at once misses errors that each pass alone would catch.',
   ['Check numbers, dates, names and units line by line.', 'Read the target aloud for flow.', 'Log errors by type: meaning, term, grammar, style.', 'Weight them: major, minor.'],
   'Sample of 500 words. Found 1 major (wrong figure), 4 minor. Score: 1 x 5 + 4 x 1 = 9 points per 500 words. Target below 5; so another pass is needed. Check: 9 points per 500 words is 1.8 per 100 words against a target of 1.0 per 100 words, so a third read is justified before delivery.',
   'Revise a flawed 300-word draft and log the errors.',
   'All major errors found and logged with a type.'),
  ('Machine tools and judgement', 'Evaluate', 3,
   'Machine output saves time but can be fluent and wrong. You are responsible for the final text. Treat the tool as a fast first drafter whose every sentence still needs a human check against the source before it reaches a client.',
   ['Check the confidentiality rules before using any online tool.', 'Compare output to source for omissions and invented facts.', 'Fix terms with the glossary.', 'Record when and how a tool was used if the client asks.'],
   'Machine draft of 500 words: 6 meaning errors found in 30 minutes of checking. Editing time 40 min vs. translating from scratch 90 min; saving 50 min, but only if the checking is thorough. Check: 90 - 40 = 50 minutes saved, and the saving is real only if all 6 errors are fixed and no new one is added during editing.',
   'Post-edit a machine draft and list the error types you found.',
   'All meaning errors fixed and none introduced.'),
  ('Confidentiality, certified work and ethics', 'Evaluate', 3,
   'Clients trust you with private documents. Some texts need official certification you may not be able to give. Trust is the product you sell; one leak or one false claim of status can end a practice and harm the client.',
   ['Sign or agree a confidentiality term before you receive private texts.', 'Do not claim certification or sworn status you do not hold.', 'Ask the competent authority which documents need certified translation.', 'Delete or return files as agreed at the end.'],
   'A client asks for a translated diploma for an official body. You are not certified: you decline or refer the job to a person who holds the status, and you note it in writing. Check: the decline costs you one short message today, and it protects you from a false claim that could end the practice later.',
   'Write a one-page confidentiality and scope statement for your service.',
   'States what you will and will not certify and how files are handled.'),
  ('Quote, delivery and growing a practice', 'Create', 3,
   'A clear quote and delivery note prevent most disputes. Clear terms also protect your time, since scope creep and unpaid extra rounds are the most common source of disagreement.',
   ['Price per word or per hour with a minimum charge.', 'State the deadline, the rounds of revision and the format.', 'Deliver with a short quality note and the glossary.', 'Ask for feedback and keep a client list.'],
   'Job of 500 words at 3 RUB per word = 1,500 RUB, minimum charge 1,000 RUB; rush rate +30 percent = 1,950 RUB. Your target is 9 RUB of income per minute worked: 2.1 h = 126 min gives 1,134 RUB, so 1,500 RUB passes. Check: 500 x 3 = 1,500; 1,500 x 1.3 = 1,950; 126 x 9 = 1,134, which is below 1,500, leaving a margin of 366 RUB.',
   'Write a quote, a delivery note and a one-month plan for finding 3 clients.',
   'Quote has scope, price, deadline and revision terms.')],
 quiz=[
  ('What must a brief state?', 'Purpose, reader, tone, format and deadline, because together they decide how close to the source words the translation should stay.'),
  ('Why ask about the date 03/04/2025?', 'Date order differs by language and country; a wrong guess would change the meaning, so ask the client before you write it.'),
  ('What is a glossary for?', 'It keeps terms consistent across a long text and between jobs for the same client, and saves research time on repeats.'),
  ('What are the two passes of revision?', 'First against the source for accuracy of meaning and numbers, then alone in the target language for reading quality and flow.'),
  ('A machine draft reads well. Is it correct?', 'Not necessarily; fluent text can omit or invent facts, so compare every sentence to the source and fix terms with the glossary.'),
  ('Can you certify a translation for an official body?', 'Only if you hold the status required by the competent authority; otherwise decline or refer the job to a person who does.'),
  ('A 500-word job at 3 RUB per word costs?', '1,500 RUB at the normal rate, and 1,950 RUB with a 30 percent rush rate added.'),
  ('Which errors are major?', 'Those that change meaning, such as wrong numbers, dates, units or names, because a reader may act on them and be harmed.'),
  ('Why leave a query note?', 'It avoids guessing, shows the client exactly where the source is unclear, and lets the client decide before the error is built in.'),
  ('What do you do with client files at the end?', 'Delete or return them as agreed in writing, and keep only what the confidentiality term allows you to keep.')],
 rubric=[
  ('Accuracy', 'Meaning error in a number or name.', 'No meaning errors.', 'Also explains choices for ambiguous passages.'),
  ('Terminology', 'Same concept translated two ways.', 'Glossary used consistently.', 'Also references sources for each term.'),
  ('Style', 'Word-by-word, hard to read.', 'Natural and fits purpose.', 'Also adapts tone to the reader.'),
  ('Process', 'No error log or brief.', 'Brief, log and revision pass done.', 'Also measures error rate over time.'),
  ('Ethics', 'Claims status not held.', 'States scope and confidentiality.', 'Also sets a file handling routine.')],
 ladder=[
  'L1 Basic: Remember the difference between a word and its meaning and why numbers, dates and names must be checked twice before anything is sent.',
  'L2 Awareness: Describe what translators do day to day, how a brief shapes a job, and what certified work involves (check the rules).',
  'L3 Foundation: Translate a short, simple text with a dictionary, keep terms consistent and check every number against the source.',
  'L4 Practitioner: Translate, revise and deliver a 500-word practical text with a glossary, an error log, a quote and a quality note.',
  'L5 Specialist: Analyse specialist texts, post-edit machine output with documented checks and manage terminology for repeat clients.',
  'L6 Advanced: Design review workflows with error scoring and train other translators to meet the agreed quality target.',
  'L7 Super expert: Create standards and lead complex multi-person projects in a field (needs years of practice and a record of results).'],
 jobs=[('Freelance translator', 'Translates texts for business clients.'), ('In-house translator', 'Translates documents for one organisation.'), ('Reviser or editor', 'Checks and improves other translators work.'), ('Localisation assistant', 'Adapts website and app text for readers in another language.'), ('Terminology assistant', 'Builds and maintains glossaries for teams.')],
 next='Related generic courses: Interpreting Skills, Technical Writing, Digital Content Localisation.')

C11 = dict(
 id='RU-11', title='Retailing', level='L4 Practitioner',
 summary='Run a small shop or online store: choose stock, set prices and margins, control inventory, serve customers and keep daily sales records.',
 outcomes=[
  ('Understand', 'Explain markup, margin, stock turn and shrinkage and how they affect shop profit.'),
  ('Apply', 'Calculate selling price, margin and reorder quantity for a product range.'),
  ('Analyse', 'Compare product lines by sales, margin and stock turn and decide which to keep.'),
  ('Evaluate', 'Judge a shop layout, a price and a promotion against customer and cash results.'),
  ('Create', 'Build a 4-week trading plan with stock, staffing, daily cash-up and a weekly review.')],
 task='Build a 4-week trading plan for a small shop with 30 product lines, including pricing, reorder points, cash-up and a weekly review.',
 condition='Desk exercise with a product list, supplier price sheet and spreadsheet; 4 hours.',
 standard='Margins correct to 0.5 percentage points, reorder points correct, daily cash-up reconciles to 0 RUB, and at least 90 percent of rubric points.',
 who='New shop owners, sales assistants moving to supervisor, online sellers and market stall holders.',
 req='Basic arithmetic and spreadsheet use.',
 safety='Retail is regulated. Business registration, tax, cash and receipt rules, consumer protection, labelling, and special rules for food, alcohol, tobacco, medicines and children products are set by the relevant federal rules and the competent authorities. Check with the competent Russian authority and a local adviser before you open or sell regulated goods. Do not sell restricted goods without the right permission, and never sell goods you cannot show were legally sourced.',
 evidence='Evidence: a price list with margins, a reorder sheet, a daily cash-up form, a stock count record and a weekly review.',
 modules=[
  ('The retail model', 'Understand', 3,
   'A shop buys goods, adds value in service and convenience, and sells at a price that covers cost and leaves a profit. Every later decision on range, price, staffing and stock traces back to this model, so learn to read it as a flow of money before you learn any single tool.',
   ['Define gross profit, net profit, fixed and variable costs.', 'Compare a shop, a market stall and an online store.', 'Choose a customer and a range that fit.', 'List the records a shop must keep.'],
   'Monthly sales 600,000 RUB, cost of goods 390,000 RUB: gross profit 210,000 RUB = 35 percent. Fixed costs 150,000 RUB leave 60,000 RUB before tax. Check: 600,000 - 390,000 = 210,000; 210,000 / 600,000 = 35 percent; 210,000 - 150,000 = 60,000, which is 10 percent of sales, so a 5 percent fall in sales would remove half of the profit.',
   'Draw the money flow of a shop from purchase to profit using your own numbers.',
   'Gross and net profit are calculated correctly.'),
  ('Choosing and buying stock', 'Analyse', 4,
   'Buy what customers will actually buy, in quantities that can be sold before cash runs out. A low unit price is a poor bargain if it buys months of slow stock, so always ask how many weeks of sales each order represents.',
   ['Use sales history, local demand and season.', 'Compare suppliers on price, minimum order and delivery.', 'Buy test quantities of new lines.', 'Check that goods are legally sourced and labelled.'],
   'Supplier A: 80 RUB for 100 units, delivery 1 week. Supplier B: 76 RUB for 500 units minimum, 3 weeks. At 40 units per week, 500 units is 12.5 weeks of stock, tying up 38,000 RUB; choose A. Check: 500 / 40 = 12.5 weeks and 500 x 76 = 38,000 RUB; one order from A is 100 x 80 = 8,000 RUB for 2.5 weeks of cover, so the saving of 4 RUB per unit is not worth 30,000 RUB more cash locked in.',
   'Compare two suppliers for three products and justify a choice.',
   'Comparison includes cash tied up and weeks of cover.'),
  ('Pricing and margin', 'Apply', 4,
   'Price must cover cost, expenses and profit, and also match what customers accept. Work from cost upward to find the floor, then look at what similar shops charge to find the ceiling, and choose a price between the two that you can defend.',
   ['Markup = (price - cost) / cost; margin = (price - cost) / price.', 'Include sales tax rules as set by the competent authority.', 'Round to prices customers expect.', 'Test and adjust.'],
   'Cost 120 RUB. Target margin 40 percent: price = 120 / (1 - 0.40) = 200 RUB. Markup = 80/120 = 66.7 percent. Check: 200 x 0.40 = 80 RUB margin and 200 - 80 = 120 RUB cost; a 40 percent markup on the same cost would give only 168 RUB, a margin of 28.6 percent, so never mix the two terms.',
   'Price 10 products to a target margin and round to a customer-friendly price.',
   'All margins within 0.5 points of target.'),
  ('Inventory control', 'Apply', 4,
   'Stock out loses sales; overstock ties up cash. Count regularly and set reorder points. A written rule replaces guesswork, so any assistant on shift can see when to order without asking the owner and without waiting for a shelf to go empty.',
   ['Reorder point = daily sales x lead time days + safety stock.', 'Count high-value lines weekly.', 'Record damage, theft and expiry as shrinkage.', 'Rotate stock first in, first out.'],
   'Sales 12 units per day, lead time 5 days, safety stock 18 units: reorder point = 12 x 5 + 18 = 78 units. Counted 74: order now. Check: 12 x 5 = 60 and 60 + 18 = 78; 74 is below 78, and ordering today means 74 - 60 = 14 units remain when the order arrives, 4 below the safety stock, so waiting even one more day risks an empty shelf.',
   'Set reorder points for 5 products from data.',
   'All five reorder points correct and a count schedule written.'),
  ('Customers and display', 'Evaluate', 3,
   'Layout, service and honesty decide whether customers return. Measure what you change, because a display that looks better but does not lift conversion or basket size has not improved the business.',
   ['Place high-demand items to draw customers through the shop.', 'Keep price labels clear and correct.', 'Greet, help and thank; handle complaints calmly.', 'Know the consumer return rules from the competent authority.'],
   'Footfall 200 people per day, 50 buy: conversion 25 percent. Average basket 900 RUB. If better display lifts conversion to 28 percent, daily sales rise from 45,000 RUB to 50,400 RUB. Check: 200 x 0.25 = 50 buyers x 900 = 45,000; 200 x 0.28 = 56 buyers x 900 = 50,400; the gain is 5,400 RUB a day, or 162,000 RUB over a 30-day month.',
   'Review a shop layout and propose 3 changes with expected effect.',
   'Changes are linked to conversion or basket size.'),
  ('Cash, receipts and daily records', 'Apply', 3,
   'Cash discipline protects you from errors and theft. Follow the receipt and cash rules set by the competent authority. A short, fixed routine done by two people at the same time each day catches mistakes while they are small and easy to trace.',
   ['Count the till at open and close.', 'Reconcile card, cash and receipts.', 'Bank takings on a schedule.', 'Keep records for the period required by law.'],
   'Float 5,000 RUB. Cash sales 38,400 RUB. Expected till 43,400 RUB. Counted 43,250 RUB: shortage 150 RUB, to investigate. Check: 5,000 + 38,400 = 43,400; 43,400 - 43,250 = 150, which is 0.4 percent of cash sales; recount, check for a wrong change given and a missed receipt, and write the cause on the form.',
   'Complete a daily cash-up form for a given day.',
   'Reconciles to 0 RUB or the difference is explained.'),
  ('Compliance and regulated goods', 'Evaluate', 3,
   'Some goods need special permission, storage and labelling. Selling them without it risks serious penalties. Treat permission as a gate that opens only with a written answer, never with a verbal hint from a supplier or a friend in the trade.',
   ['List the goods you plan to sell and whether any are regulated.', 'Ask the competent authority what registration, labelling and permission applies.', 'Keep supplier documents that show origin.', 'Refuse to sell what you cannot show is legal.'],
   'Range of 30 lines: 22 general, 5 food, 3 regulated. The 3 regulated lines are held until the permission is confirmed in writing; that is 10 percent of lines and 18 percent of planned sales. Check: 3 / 30 = 10 percent; if planned sales are 600,000 RUB a month, the held lines are worth 108,000 RUB, so the opening plan must work without them.',
   'Audit a product range and flag every regulated line with a next step.',
   'Every regulated line flagged with a named authority to ask.'),
  ('Trading plan and weekly review', 'Create', 4,
   'A plan turns knowledge into a routine: order, display, sell, count, review. Keep it to one page and one change a week so you can tell which action moved the numbers.',
   ['Set weekly sales and margin targets.', 'Plan staffing around busy hours.', 'Review the top and bottom 5 lines.', 'Change one thing each week.'],
   'Target week 150,000 RUB sales at 35 percent margin = 52,500 RUB gross. Actual 138,000 RUB at 34 percent = 46,920 RUB. Gap 5,580 RUB; action: reduce slow lines, raise price of 3 lines by 5 percent. Check: 52,500 - 46,920 = 5,580; the shortfall comes from 12,000 RUB less sales and 1 point less margin, so both causes need an action, not only a price rise.',
   'Build the 4-week plan and a weekly review sheet.',
   'Plan has targets, staffing, reorder and review steps.')],
 quiz=[
  ('What is margin on a 200 RUB price with 120 RUB cost?', '(200-120)/200 = 40 percent, meaning 80 RUB of every 200 RUB sale is gross profit before shop expenses are paid.'),
  ('What is markup on the same item?', '80/120 = 66.7 percent, because markup divides the profit by the cost, not by the price, so it is always larger than margin.'),
  ('How do you calculate a reorder point?', 'Daily sales x lead time in days + safety stock; when the count falls to that number, place the order at once.'),
  ('What is shrinkage?', 'Stock lost to damage, theft, expiry or counting error; record it by line so you can see where the losses are concentrated.'),
  ('Why count the till at open and close?', 'To reconcile cash against sales and receipts and find errors early, while the day is fresh and the cause is easy to trace.'),
  ('What does conversion mean?', 'The share of visitors who buy; 50 buyers from 200 visitors is 25 percent, and raising it is cheaper than finding new visitors.'),
  ('A regulated product has no permission yet. What do you do?', 'Do not sell it; ask the competent authority what applies and wait for written confirmation before it goes on the shelf.'),
  ('Why compare weeks of cover for a supplier deal?', 'A cheap unit price can tie up too much cash in slow stock, so compare the cash locked and the weeks it will take to sell.'),
  ('What is FIFO?', 'First in, first out: sell the oldest stock first, which reduces expiry and damage losses and keeps the shelf fresh.'),
  ('Why change only one thing per week?', 'So you can see which change caused the result; two changes at once hide the cause and make the weekly review guesswork.')],
 rubric=[
  ('Pricing', 'Margin wrong by over 0.5 points.', 'Margins correct and prices rounded.', 'Also tests price changes with data.'),
  ('Inventory', 'No reorder points.', 'Reorder points correct and count schedule set.', 'Also models stock turn by line.'),
  ('Cash control', 'Does not reconcile.', 'Reconciles or explains the difference.', 'Also sets controls to prevent errors.'),
  ('Compliance', 'Regulated goods ignored.', 'Regulated lines flagged with a next step.', 'Also builds a document file per supplier.'),
  ('Review', 'No measures.', 'Targets and gap shown with one action.', 'Also tracks trend over four weeks.')],
 ladder=[
  'L1 Basic: Remember what margin, markup and stock mean and why a price must cover cost, expenses and a profit.',
  'L2 Awareness: Describe how a shop makes money, which records it keeps and the rules it must follow (check them).',
  'L3 Foundation: Calculate a selling price from a target margin, set a simple reorder point and run a till cash-up.',
  'L4 Practitioner: Plan, price and run a small shop for four weeks with stock counts, cash records and a weekly review.',
  'L5 Specialist: Analyse lines by margin and stock turn, redesign the range and keep regulated goods inside the rules.',
  'L6 Advanced: Design systems for several shops, negotiate supplier terms and train staff to meet set targets.',
  'L7 Super expert: Create a retail concept and network strategy with proven results (needs years of practice).'],
 jobs=[('Shop assistant', 'Serves customers and keeps displays and the till accurate.'), ('Shop supervisor', 'Runs shifts, counts stock and supervises staff.'), ('Buyer assistant', 'Collects data and orders stock.'), ('Online store operator', 'Lists, prices and ships goods to customers.'), ('Small shop owner', 'Runs the whole business within the rules.')],
 next='Related generic courses: Small Business Bookkeeping, Customer Service, E-commerce.')

C12 = dict(
 id='RU-12', title='Sporting Goods', level='L4 Practitioner',
 summary='Select, fit, sell, maintain and advise on sporting goods: equipment sizing, safety standards, stock seasonality, repairs and honest advice for different sports.',
 outcomes=[
  ('Understand', 'Explain how sport, user level and body size decide the right equipment.'),
  ('Apply', 'Measure and fit a customer for a common item such as footwear, a helmet or a bicycle.'),
  ('Analyse', 'Compare products on safety, durability, fit and price for a stated user.'),
  ('Evaluate', 'Judge when a used or damaged item is unsafe and must not be sold or used.'),
  ('Create', 'Build a seasonal range plan with stock, display and an advice sheet.')],
 task='Advise three customers on equipment, build a seasonal range plan for a small sporting goods shop, and write a safety and returns sheet.',
 condition='Desk exercise with product data, a measuring guide and a spreadsheet; 4 hours.',
 standard='Fit and size calculations correct, safety limits stated, range plan within a 600,000 RUB buying budget, and at least 90 percent of rubric points.',
 who='Sports shop staff, club equipment managers, online sellers and parents or coaches who buy for others.',
 req='Basic arithmetic. Interest in sport is helpful.',
 safety='Sporting goods can cause injury if wrong, damaged or misused: helmets, climbing and water-safety gear, protective equipment and children products need special care. Product conformity, labelling and consumer rules are set by the relevant federal rules and the competent authority. This course gives general guidance, not medical or coaching advice. Check with the competent Russian authority, the maker instructions and a qualified coach. Never sell or advise use of safety gear that is damaged, expired or past its life.',
 evidence='Evidence: a fitting record, a product comparison, a safety check sheet, a seasonal range plan and a returns procedure.',
 modules=[
  ('Sport, user and need', 'Understand', 3,
   'The right item depends on who uses it, how often and where. A beginner and a racer need different things. Start every sale with questions, not products, because the answers narrow a wall of choices to two or three items that suit the person and their budget.',
   ['Ask about sport, level, frequency, place, budget and goals.', 'Separate need from want.', 'Note health, age and size limits.', 'Record the answers on a simple form.'],
   'Customer: adult, beginner runner, 3 runs per week, 5 km, road. Need: cushioned road shoes, budget 6,000 RUB. Not needed: trail spikes or a 15,000 RUB racing model. Check: 6,000 RUB is 40 percent of the 15,000 RUB racing price, and a beginner running 3 times a week for 5 km covers about 15 km a week, so 700 km of shoe life lasts roughly 47 weeks.',
   'Fill the needs form for three different customers.',
   'Each form leads to a clear item type and budget band.'),
  ('Sizing and fit', 'Apply', 4,
   'A poorly fitted item causes blisters, strain or injury. Measure, do not guess. Check both feet, because most people have one slightly larger foot, and fit the larger one; ask the customer to walk, stand and move as in the sport before you confirm the size.',
   ['Measure foot length in the afternoon, standing.', 'Leave about 10 to 12 mm of space at the toe for running shoes.', 'Size helmets by head circumference; it must sit level and not move.', 'Size bicycles by rider height and inside leg.'],
   'Foot length 265 mm plus 12 mm toe space = 277 mm internal length. Choose the size whose insole is about 277 mm, per the maker size chart. Check: 265 + 12 = 277 mm; if the nearest insole is 275 mm the toe space falls to 10 mm, still inside the 10 to 12 mm range, while 270 mm would leave only 5 mm and must be rejected.',
   'Measure two people and choose a size from a chart you are given.',
   'Measurements correct to 2 mm and size choice justified.'),
  ('Safety and standards', 'Evaluate', 4,
   'Protective gear works only if it meets the rules, fits and is undamaged. Check what the maker says. Write down the date, the marking and the condition on a check sheet for each item, so that a safety decision is a recorded fact and not a feeling at the till.',
   ['Look for the conformity marking the competent authority requires.', 'Check manufacture date and maker life guidance.', 'Replace a helmet after a significant impact even if it looks fine.', 'Never advise gear beyond the maker stated use.'],
   'Helmet bought 6 years ago, maker guidance suggests replacement after 5 years or after any hard impact. Decision: do not sell it as new, advise replacement. Check: 6 years is more than the 5 year guidance by 1 year, so it fails on age alone; a helmet that is 4 years old but has taken a hard impact also fails, whatever it looks like.',
   'Inspect a list of ten described items and mark safe, repair or retire.',
   'All unsafe items retired with a reason.'),
  ('Comparing products', 'Analyse', 3,
   'Compare on fit, safety, weight, durability, warranty and price per year of use. A fair comparison uses the same criteria for every product, so write the criteria first and score each item without looking at the price.',
   ['List criteria that matter for the user.', 'Weight them.', 'Calculate cost per use or per season.', 'Be honest about trade-offs.'],
   'Shoe A 5,500 RUB lasts 700 km = 7.86 RUB/km. Shoe B 8,000 RUB lasts 1,100 km = 7.27 RUB/km. B is cheaper per km but costs 2,500 RUB more now; advise by budget and mileage. Check: 5,500 / 700 = 7.86 and 8,000 / 1,100 = 7.27, a gap of 0.59 RUB per km; a runner doing 15 km a week saves about 8.9 RUB a week, so the extra 2,500 RUB takes more than 5 years to repay, and A suits this customer.',
   'Compare three products for one customer in a table.',
   'Table has weights, cost per use and a clear recommendation.'),
  ('Seasonal stock and buying', 'Create', 4,
   'Sport sells in seasons. Buy early enough to have stock and late enough to sell it. Cash is the limit, so split the budget by risk first and by product second, and keep a share unspent for reorders of lines that sell faster than planned.',
   ['Map the sport seasons for your region.', 'Plan opening buy, reorder and markdown dates.', 'Limit risky lines to small buys.', 'Plan markdowns to clear stock without losing money.'],
   'Winter budget 600,000 RUB: 55 percent core (330,000 RUB), 30 percent seasonal (180,000 RUB), 15 percent test lines (90,000 RUB). Markdown week 8 at 20 percent off for items with over 6 weeks cover. Check: 330,000 + 180,000 + 90,000 = 600,000 RUB, so the split uses exactly the budget; a 20 percent markdown on a 4,000 RUB item gives 3,200 RUB, which must still be above cost to avoid a loss.',
   'Build a quarter range plan with budget split.',
   'Splits sum to the budget and markdown rules are dated.'),
  ('Care, repair and used goods', 'Apply', 3,
   'Good care extends life and keeps customers safe. Know what you can fix and what you must refer. Brakes, helmets, straps and anything that holds a person up are safety critical; cosmetic faults never justify the same urgency or cost.',
   ['Clean, dry and store gear as the maker advises.', 'Do simple repairs only within your skill.', 'Refer safety-critical repairs to a qualified person.', 'Sell used goods only if safe and described honestly.'],
   'Used bicycle: tyres 40 percent worn, brake pads 60 percent worn. Replace pads (safety critical) 700 RUB; tyres can wait 500 km; price drops 1,200 RUB. Check: the pads cost 700 RUB and the future tyre job about 500 RUB, so the total repair need is 1,200 RUB, which equals the price drop; the pads must be changed before sale, the tyres can be disclosed in writing.',
   'Write a care sheet and a used-goods checklist.',
   'Checklist separates safety-critical from cosmetic faults.'),
  ('Advice, honesty and returns', 'Evaluate', 3,
   'Trust brings customers back. Honest advice, clear returns and no medical claims. A customer who hears an honest no today, such as advice to buy a cheaper item, often returns and brings friends, while a false promise brings a refund and a complaint.',
   ['Do not make health or performance promises.', 'Explain the return rules from the competent authority and your policy.', 'Record complaints and fix causes.', 'Refer injury questions to a health professional.'],
   'Month: 240 sales, 12 returns = 5 percent. Cause: 7 size errors. Action: add a second fit check; target 3 percent. Check: 12 / 240 = 5 percent; 7 of 12 returns, 58 percent, were size errors; at 3 percent the shop would have 7 returns from 240 sales, so removing the 7 size errors would reach nearly 2 percent.',
   'Write a returns policy and an advice script.',
   'Policy is clear, fair and without false claims.'),
  ('Shop plan and review', 'Create', 4,
   'Combine range, fit, safety and records into a monthly plan. One page with dated actions and a named owner for each is enough; the plan only works if someone checks it at the end of the month.',
   ['Set sales and margin targets.', 'Schedule staff training on fitting.', 'Run a monthly safety audit of display and rental gear.', 'Review returns and stock.'],
   'Monthly sales 420,000 RUB at 33 percent gross margin = 138,600 RUB. Fit training 4 h per person. Audit finds 3 items retired. Check: 420,000 x 0.33 = 138,600 RUB; if the 3 retired items cost 9,000 RUB in total, that loss is 6.5 percent of the monthly gross profit, a reason to audit earlier next month.',
   'Build a monthly plan with targets and audit dates.',
   'Plan has targets, training, audit and review.')],
 quiz=[
  ('How much toe space for running shoes?', 'About 10 to 12 mm between the longest toe and the shoe end, measured with the customer standing, so the toes do not hit the front on downhill steps.'),
  ('When should a helmet be replaced?', 'After a significant impact, even if it looks fine, or when it reaches the maker life guidance, whichever comes first.'),
  ('Cost per km of a 5,500 RUB shoe lasting 700 km?', '7.86 RUB per km, found by dividing the price by the expected distance; compare it with other shoes before advising.'),
  ('Why measure feet in the afternoon?', 'Feet swell during the day, so an afternoon measure avoids buying a size that becomes tight later in a long run or walk.'),
  ('Can you promise a medical benefit from a product?', 'No; make no health or performance promises and refer health questions to a qualified professional.'),
  ('A bicycle brake pad is 60 percent worn. Safety critical?', 'Yes, brakes are safety critical; replace the pads or refer the job to a qualified person before the bicycle is sold or used.'),
  ('Why use small buys for test lines?', 'To limit risk on unproven products, so a miss costs a small share of the budget and leaves cash for proven lines.'),
  ('What goes on a needs form?', 'Sport, level, frequency, place, budget and goals, plus any health, age or size limits that change the choice of item.'),
  ('Why track returns?', 'To find and fix causes such as size errors, set a target rate and show whether the fix, such as a second fit check, worked.'),
  ('Who sets conformity rules for gear?', 'The relevant federal rules and the competent authority; you check the marking and the maker instructions and ask them when unsure.')],
 rubric=[
  ('Fit', 'Wrong size or no measure.', 'Measured and sized correctly.', 'Also explains fit trade-offs.'),
  ('Safety', 'Unsafe item passed.', 'All unsafe items retired.', 'Also builds an audit routine.'),
  ('Comparison', 'No cost per use.', 'Weighted table and recommendation.', 'Also tests with different users.'),
  ('Range plan', 'Budget exceeded.', 'Within budget with dated markdowns.', 'Also models cash flow by week.'),
  ('Honesty', 'Makes health claims.', 'Advice is truthful and referred where needed.', 'Also trains others in the script.')],
 ladder=[
  'L1 Basic: Remember that the right size and condition of gear matter for safety and that damaged protective gear must not be used.',
  'L2 Awareness: Describe sport categories, the main fitting checks and the safety duties around gear (check the rules).',
  'L3 Foundation: Measure and fit a customer for one item, record the size and explain why it was chosen.',
  'L4 Practitioner: Advise, compare, buy and audit a small sporting goods range within a budget, with safety and returns records.',
  'L5 Specialist: Analyse sport segments, design technical fitting services and set targets for returns and stock cover.',
  'L6 Advanced: Design supplier, safety and training systems for several shops and review results against targets.',
  'L7 Super expert: Create standards and a sector-wide safety programme with a record of results (needs years of practice).'],
 jobs=[('Sports shop assistant', 'Advises and fits customers.'), ('Equipment manager (club)', 'Buys, stores and checks gear for a team.'), ('Bicycle or gear technician', 'Does basic repair and safety checks within skill.'), ('Online sporting goods seller', 'Lists and ships gear with accurate descriptions.'), ('Buyer assistant', 'Plans seasonal ranges.')],
 next='Related generic courses: Retailing, Customer Service, Fitness Coaching Basics.')

C13 = dict(
 id='RU-13', title='Condiments Business', level='L4 Practitioner',
 summary='Make, cost, label, store and sell sauces, spice blends and similar condiments safely: recipes, batch costing, hygiene, shelf life, labelling and small-scale selling.',
 outcomes=[
  ('Understand', 'Explain how acidity, salt, sugar, heat and packaging control spoilage in condiments.'),
  ('Apply', 'Scale a recipe by weight and calculate yield, cost per jar and selling price.'),
  ('Analyse', 'Compare hazards in a recipe and identify the control points that must be monitored.'),
  ('Evaluate', 'Judge whether a product and kitchen meet hygiene, labelling and registration needs.'),
  ('Create', 'Build a batch record, label draft and launch plan for one condiment.')],
 task='Scale and cost one condiment recipe, write a hazard and control sheet, draft a label and plan a small launch.',
 condition='Desk exercise with a recipe, price list and spreadsheet; 4 hours; no production claims.',
 standard='Yield and cost correct to 2 percent, every control point has a limit and a record, label has all required elements, and at least 90 percent of rubric points.',
 who='Home cooks becoming small producers, market sellers, small food shops and cafe owners adding a house sauce.',
 req='Kitchen basics and arithmetic.',
 safety='Food production is regulated. Registration, premises approval, hygiene training, product safety checks, labelling, allergen information, traceability and shelf-life claims are set by the relevant federal rules and the competent authorities. Low-acid, oil-based or home-canned products can carry serious risks such as botulism; do not sell them without proper process validation. Check with the competent Russian authority and a local adviser before you sell food. This course does not replace laboratory testing or official approval.',
 evidence='Evidence: a scaled recipe, a batch costing sheet, a hazard and control table, a label draft and a launch plan.',
 modules=[
  ('Food safety basics for condiments', 'Understand', 4,
   'Condiments last because of acid, salt, sugar, low water or heat treatment. Remove or weaken one of those and spoilage or illness can follow. Safe condiments are designed, measured and recorded, never judged by taste or smell, because dangerous bacteria and their toxins give no warning.',
   ['Explain pH, water activity and why they matter.', 'List hazards: biological, chemical, physical, allergens.', 'Know the danger of low-acid and oil-based products without control.', 'Wash hands, separate raw and ready foods, clean and sanitise surfaces.'],
   'A sauce at pH 3.8 is acid enough to limit many bacteria, while the same sauce with added garlic in oil at pH 5.5 is not. The second needs expert process control or must not be sold. Check: 5.5 - 3.8 = 1.7 pH units, a fifty-fold change in acidity; the pH must be measured with a calibrated meter on each batch, and a result above the confirmed limit means the batch is held back.',
   'Classify five condiments as high or low risk with a reason.',
   'Reasons refer to acid, water activity or process.'),
  ('Recipes by weight and scaling', 'Apply', 3,
   'Weigh, do not measure by volume. A recipe in percentages scales to any batch. Weigh every ingredient on a scale checked against a known weight, and write the real figure on the batch sheet, not the planned one.',
   ['Convert the recipe to grams and percent of total.', 'Allow for cooking loss.', 'Compute yield by weighing before and after.', 'Record each batch with lot numbers.'],
   'Recipe: 4.0 kg tomato, 0.6 kg sugar, 0.2 kg salt, 0.4 kg vinegar = 5.2 kg raw. After cooking the batch weighs 4.4 kg: loss 15.4 percent. Jars of 250 g: 17 jars (4.25 kg) with 150 g left over. Check: 4.0 + 0.6 + 0.2 + 0.4 = 5.2 kg; 5.2 - 4.4 = 0.8 kg lost, 0.8 / 5.2 = 15.4 percent; 17 x 250 g = 4,250 g and 4,400 - 4,250 = 150 g. For a 10 kg batch multiply each weight by 10 / 5.2 = 1.92.',
   'Scale a recipe to a 10 kg batch and compute yield.',
   'Weights and yield correct to 2 percent.'),
  ('Costing a batch', 'Apply', 4,
   'Know cost per jar before setting a price. Include ingredients, packaging, labour, energy and waste. Many small producers underprice because they forget their own time; a price that pays for ingredients only will end the business when the first big cost rises.',
   ['Cost each ingredient per kg.', 'Add jars, lids, labels and energy.', 'Add labour time at a fixed hourly rate.', 'Add a waste allowance of 3 to 5 percent.'],
   'Batch 17 jars. Ingredients 1,150 RUB, jars and lids 17 x 22 = 374 RUB, labels 51 RUB, energy 90 RUB, labour 3 h x 300 = 900 RUB. Total 2,565 RUB; per jar 150.9 RUB. With a 35 percent margin: price = 150.9 / 0.65 = 232 RUB. Check: 1,150 + 374 + 51 + 90 + 900 = 2,565; 2,565 / 17 = 150.9; a 4 percent waste allowance adds about 103 RUB to the batch, giving 2,668 RUB or 157 RUB per jar and a price of 241 RUB.',
   'Cost a 10 kg batch and set a price.',
   'Cost per jar within 2 percent.'),
  ('Hazards and control points', 'Analyse', 4,
   'Find where things can go wrong and set a measurable limit and a record at each point. A limit must be a number you can measure, such as a temperature or a time, and the monitor must be a tool, not an opinion.',
   ['Draw the process: receive, store, prepare, cook, fill, seal, cool, store.', 'Mark the steps where a hazard is controlled.', 'Set a limit, how to monitor, and what to do if it fails.', 'Keep monitoring records.'],
   'Control point: hot fill at not less than 85 C, held 2 minutes, checked with a calibrated thermometer each batch. If 82 C is recorded: re-heat, and record the correction. Check: 85 - 82 = 3 C below the limit, so the batch is not filled until it reaches 85 C again and holds for the full 2 minutes; the thermometer is checked against ice water at 0 C before the shift.',
   'Build a hazard and control table for one recipe.',
   'Each control point has limit, monitor and corrective action.'),
  ('Packaging, storage and shelf life', 'Evaluate', 3,
   'Shelf life is shown by testing, not guessing. Packaging protects but can fail. A poor seal lets air and microbes in, so test seals on every batch and keep a few jars from each lot as retained samples to check later.',
   ['Choose containers and seals suited to hot fill.', 'Check seals and cool as planned.', 'Store cool, dry and dark; use oldest first.', 'Set the date mark only after expert advice or testing.'],
   'Trial: 3 jars held at 25 C for 12 weeks, checked every 2 weeks. All passed on appearance, smell and pH; a lab confirms. A conservative label of 6 months is proposed, pending the competent authority rules. Check: 12 weeks at 25 C does not prove 6 months, so the label stays provisional; checks every 2 weeks give 6 readings per jar, 18 readings for 3 jars, and any failure resets the proposed date.',
   'Write a shelf-life test plan for one product.',
   'Plan has sample number, conditions, checks and a decision rule.'),
  ('Labels and allergen information', 'Create', 3,
   'A label must be truthful and carry the information required by the rules. Allergens must be clear. A buyer with an allergy relies on the label alone, so an error here can cause real harm; have a second person read every label against the recipe before printing.',
   ['List name, ingredients by weight order, net quantity, date mark, storage, producer details.', 'Highlight allergens as the rules require.', 'Avoid unproven health claims.', 'Add the lot number for traceability.'],
   'Label for 250 g jar: name, ingredients (tomato 77 percent, sugar, vinegar, salt), net 250 g, lot A0412, storage after opening. Check with the competent authority for the full list. Check: tomato 4.0 kg of 5.2 kg raw is 76.9 percent, shown as 77 percent, and ingredients are listed in descending weight order: tomato, sugar, vinegar, salt.',
   'Draft a label and mark what you must confirm with the authority.',
   'No false claims and allergens clear.'),
  ('Registration, premises and compliance', 'Evaluate', 3,
   'Selling food needs approval and a suitable place. A home kitchen may not qualify. Ask before you buy equipment or print labels, since approval may require a separate room, safe water, waste handling and trained staff that change your costs.',
   ['Ask which registration your production needs.', 'Check premises, water, waste and pest control.', 'Train staff in food hygiene.', 'Keep supplier and batch records for recall.'],
   'Recall drill: given lot A0412, find the sold jars within 60 minutes using the sales log: 17 jars, 14 sold to 5 buyers, 3 in stock. Check: 14 + 3 = 17 jars accounted for, with 0 missing; the drill passes only if all 17 are found, the 5 buyers are contacted and the 3 jars are held, all within the 60 minutes.',
   'Write a compliance checklist and run a recall drill on sample data.',
   'Checklist names an authority question for each item; drill under 60 minutes.'),
  ('Launch and selling', 'Create', 4,
   'Start small, test with real buyers and track the numbers. A small launch limits waste and gives honest feedback on taste, price and jar size before you commit more cash and time.',
   ['Choose a channel: stall, shop, online, local cafe.', 'Plan batch size to demand.', 'Track sales, waste and feedback.', 'Change one thing at a time.'],
   'Week 1: 34 jars made, 28 sold at 232 RUB = 6,496 RUB, 6 unsold. Gross profit per jar 81 RUB x 28 = 2,268 RUB. Next batch: 28 jars. Check: 28 x 232 = 6,496; 232 - 151 = 81 and 81 x 28 = 2,268; the 6 unsold jars cost about 906 RUB, so the net gain is 1,362 RUB, and the sell-through rate is 28 / 34 = 82 percent.',
   'Write a 4-week launch plan with batch sizes and review dates.',
   'Plan links batch size to sales data.')],
 quiz=[
  ('Why does acid help preserve a sauce?', 'A low pH limits the growth of many bacteria, so acid is a measured control, and the pH of each batch must be checked and recorded.'),
  ('What is the risk with garlic in oil?', 'Low acid and no oxygen can allow botulism; do not sell such a product without expert process control and approval.'),
  ('Why weigh, not measure by volume?', 'Weight is accurate and scalable, while volume changes with packing and temperature; percentages by weight scale to any batch size.'),
  ('Batch 17 jars cost 2,565 RUB. Cost per jar?', 'About 150.9 RUB, found by dividing the batch cost by the number of jars, before waste allowance and margin are added.'),
  ('What is a critical control point?', 'A step where a hazard is controlled, with a measurable limit, a way to monitor it, a corrective action and a record.'),
  ('Who decides your date mark?', 'Testing or expert advice under the rules of the competent authority; you do not choose it by guessing or by copying another product.'),
  ('What must a label show for allergens?', 'They must be clearly identified as the rules require, and a second person should check the label against the recipe.'),
  ('Why keep lot numbers?', 'For traceability and recall, so you can find every jar from a faulty batch and the buyers quickly, within the 60 minute drill target.'),
  ('Can a home kitchen always be used for sales?', 'No; check premises, water, waste and registration rules with the competent authority before you buy equipment or sell.'),
  ('What if a hot fill reads below the limit?', 'Re-heat to the limit, hold the full time, record the correction and review why it happened so it does not repeat.')],
 rubric=[
  ('Recipe and costing', 'Yield or cost over 2 percent off.', 'Within 2 percent.', 'Also analyses cost drivers.'),
  ('Hazards', 'No limits or records.', 'Limits, monitor and action for each point.', 'Also validates limits with a source.'),
  ('Label', 'Missing required items or false claim.', 'Complete and truthful.', 'Also checked against the authority rules.'),
  ('Compliance', 'Ignores registration.', 'Checklist with authority questions.', 'Also completes a recall drill.'),
  ('Launch', 'No data link.', 'Batch size tied to sales.', 'Also plans channels and tests.')],
 ladder=[
  'L1 Basic: Remember basic kitchen hygiene, hand washing and why condiments spoil when acid, salt or heat control is weak.',
  'L2 Awareness: Describe the rules for selling food, the main hazards in condiments and why home-canned products can be unsafe.',
  'L3 Foundation: Make and cost a simple batch by weight with a record of lot, yield, temperatures and cost per jar.',
  'L4 Practitioner: Scale, cost, label and plan the launch of one condiment with safety controls, records and a recall drill.',
  'L5 Specialist: Analyse hazards for a product range, design validation tests and set evidence-based shelf life with experts.',
  'L6 Advanced: Design a quality system for a registered small producer and train staff to run and audit it.',
  'L7 Super expert: Create new products and lead a certified production site with a record of results (needs years of practice).'],
 jobs=[('Small-batch producer', 'Makes and sells condiments within the rules.'), ('Kitchen assistant (production)', 'Follows recipes and records.'), ('Quality assistant', 'Monitors temperatures and records.'), ('Market seller', 'Sells packaged products with accurate labels.'), ('Product developer assistant', 'Tests and costs new recipes.')],
 next='Related generic courses: Food Hygiene, Food Processing, Small Business Bookkeeping.')

C14 = dict(
 id='RU-14', title='Cleaning Business', level='L4 Practitioner',
 summary='Start and run a cleaning service: scoping jobs, products and equipment, safe methods, pricing, quality checks, staff and client contracts.',
 outcomes=[
  ('Understand', 'Explain cleaning, disinfecting and sanitising and which one a job needs.'),
  ('Apply', 'Calculate time, labour and price for a cleaning job from floor area and task rates.'),
  ('Analyse', 'Compare chemicals and methods for risk, cost and surface compatibility.'),
  ('Evaluate', 'Judge a finished job against a written checklist and decide what to redo.'),
  ('Create', 'Build a job scope, quote, risk sheet and quality checklist for a client.')],
 task='Scope and quote a cleaning job for a 120 square metre office, with a risk sheet and a quality checklist.',
 condition='Desk exercise with floor plan, rate table and spreadsheet; 4 hours.',
 standard='Time and price correct to 5 percent, every chemical has a safe-use note, checklist covers all areas, and at least 90 percent of rubric points.',
 who='People starting a cleaning service, supervisors in cleaning teams and facilities staff.',
 req='Basic arithmetic. Physical fitness is useful for real work.',
 safety='Cleaning chemicals can burn skin, damage lungs and react dangerously if mixed: never mix products, always read the maker label and safety sheet. Staff need training, protective equipment and safe lifting. Work in medical, food or hazardous sites needs special rules. Registration, tax, employment, insurance and waste rules are set by the relevant federal rules and the competent authority. Check with the competent Russian authority and a local adviser before you start, and never clean biohazard or asbestos areas without qualified authorisation.',
 evidence='Evidence: a job scope, a time and price calculation, a chemical safety table, a quality checklist and a client agreement outline.',
 modules=[
  ('Clean, disinfect, sanitise', 'Understand', 3,
   'Cleaning removes dirt; disinfecting kills germs on a surface; sanitising reduces them to a safe level. Dirt must be removed first, because soil shields germs from the product and uses it up. A client who asks for disinfection usually needs cleaning first.',
   ['Define each term with an example.', 'Choose the right level for an office, kitchen and bathroom.', 'Learn contact time: a disinfectant needs time on a wet surface.', 'Work from clean to dirty and top to bottom.'],
   'A disinfectant label says 5 minutes contact. Spray at 10:00, wipe at 10:05 or later. Wiping at 10:01 gives no assurance of disinfection. Check: 10:00 + 5 min = 10:05. For 20 desks sprayed at 2 minutes each, the last desk is finished at 10:40, so it is wiped no earlier than 10:45; plan the route so each desk stays wet for the full 5 minutes.',
   'Write a plan listing which surfaces need cleaning only and which need disinfection, with a contact time and a wipe time for each disinfected surface, for at least 8 surfaces.',
   'Each choice has a reason and a contact time where relevant; all 8 surfaces are classified and every wipe time is at or after spray time plus contact time.'),
  ('Chemicals and safety', 'Evaluate', 4,
   'Chemicals do the work but can harm. Read the label and safety sheet, dilute correctly and never mix. Measure with a marked jug, not by eye, because too strong a mix damages surfaces and skin while too weak a mix fails to clean and wastes time.',
   ['Keep products in labelled containers.', 'Wear gloves and eye protection as the label advises.', 'Never mix bleach with acids or ammonia products.', 'Ventilate and store out of reach of children.'],
   'Concentrate diluted 1:40 means 1 part to 40 parts water, 41 parts in total. For a 10 L bucket: 10 000 mL / 41 = 244 mL concentrate plus 9.76 L water. Check: 244 x 40 = 9,760 mL water, and 244 + 9,760 = 10,004 mL, close to 10 L. Mark the bucket at the dose. A 5 L bottle of concentrate fills about 20 buckets (5,000 / 244 = 20.5).',
   'Complete a safe-use table for five products, giving dilution, contact time, protective equipment, storage and one incompatible pair for each, and calculate the dose for a 5 L bucket.',
   'Dilutions correct to within 5 mL, incompatible pairs flagged for all five products, and no product listed without a protective equipment note.'),
  ('Equipment and methods', 'Apply', 3,
   'Good tools save time and protect surfaces. Colour coding prevents cross-contamination. A small set of well-chosen tools, washed and stored properly, is cheaper over a year than cheap tools that scratch surfaces or spread germs between rooms.',
   ['Colour code cloths: for example red for toilets, blue for general.', 'Match method to surface: damp mop, scrub, vacuum with filter.', 'Maintain and wash tools after use.', 'Use wet-floor signs.'],
   'Cloth set: 4 colours x 6 cloths = 24 cloths; wash at 60 C. Mop heads: replace after 40 washes. With 5 mop heads each used and washed once a day, every head reaches 40 washes after 40 working days, which is 8 working weeks. Buy 5 replacements every 8 weeks and track the count on a log.',
   'Design a colour-code plan for a small office with toilets, kitchen, desks and floors, listing cloth colour, mop head, wash temperature and storage place for each area.',
   'No cloth used across toilet and food areas, every area has a colour, and the plan includes a replacement schedule with a stated wash count.'),
  ('Scoping and timing a job', 'Apply', 4,
   'Time estimates decide profit. Use production rates per area and task, and add set-up and travel time. Measure rather than guess, and test your rates by timing a real job once, then update the table so quotes improve with each contract.',
   ['Walk the site and measure areas.', 'Use rates such as m2 per hour for each task.', 'Add 15 percent for set-up, breaks and travel.', 'Record special tasks such as windows.'],
   'Office 120 m2: vacuum and mop at 60 m2/h = 2.0 h; toilets 2 x 0.5 h = 1.0 h; desks and bins 0.75 h. Subtotal 3.75 h + 15 percent = 4.3 h. Check: 3.75 x 0.15 = 0.56, and 3.75 + 0.56 = 4.31 h, about 4 h 19 min. This is one visit for one person, or about 2 h 10 min each for a team of two.',
   'Time a 150 m2 job from given rates, including two toilets, one kitchen and a window task, then add the 15 percent allowance and show each line in a table.',
   'Total within 5 percent of the model answer, each task has a rate, and the allowance is added once and shown separately.'),
  ('Pricing and quoting', 'Create', 3,
   'A quote covers labour, products, equipment wear, travel, insurance, tax and profit. A price that only covers wages loses money once overhead and idle time appear, so build it line by line and keep the working visible for the client conversation.',
   ['Compute hourly cost per worker including social charges as set by law.', 'Add materials and overhead.', 'Add a margin.', 'State scope, frequency and exclusions in writing.'],
   '4.3 h x 400 RUB = 1,720 RUB labour; products 120 RUB; travel 150 RUB; subtotal 1,990 RUB; overhead 10 percent = 199 RUB; total cost 2,189 RUB. At 25 percent margin: 2,189 / 0.75 = 2,919 RUB per visit. Check: 25 percent of 2,919 is 730, and 2,919 - 730 = 2,189. For 12 visits a month = 35,028 RUB.',
   'Write a quote with scope and exclusions for the 120 m2 office, showing each cost line, the margin and the monthly total for 8 visits.',
   'Price correct to 5 percent, exclusions stated, and the monthly total equals visits multiplied by the per-visit price.'),
  ('Quality checks and complaints', 'Evaluate', 3,
   'Quality is what the client sees on arrival. A checklist and photos prevent disputes. Inspect after a job, not only after a complaint, and record the result so that patterns such as a repeatedly missed skirting board lead to retraining instead of blame.',
   ['Build a room-by-room checklist.', 'Score each item pass or redo.', 'Photograph before and after where agreed.', 'Fix complaints within 24 hours and log the cause.'],
   'Checklist of 40 items; inspection finds 3 fails: 37 / 40 = 92.5 percent pass. Target 95 percent needs 38 passes, at most 2 fails, so this job is one item short and the failed items are retrained. Check: 0.95 x 40 = 38.',
   'Create a 30-item checklist covering entrance, desks, floors, kitchen and toilets, then score a sample job with 4 fails and state whether it meets a 90 percent target.',
   'Checklist covers all rooms, scoring is correct to one decimal place (86.7 percent for 4 fails), and the verdict follows from the target.'),
  ('Staff, contracts and legal basics', 'Evaluate', 3,
   'People are the service. Training, fair pay, insurance and clear contracts protect everyone. A written agreement settles who provides water and equipment, who holds keys and what happens if a visit is missed, which prevents most disputes before they start.',
   ['Train staff on chemicals, lifting and site rules.', 'Check the employment or contractor rules with the competent authority.', 'Write a service agreement with scope, price, access, liability and notice.', 'Keep keys and client data safe.'],
   'New staff induction of 4 hours covers 8 topics, about 30 minutes each (240 / 8). Test of 10 questions, pass mark 8, so 80 percent. A worker scoring 7 repeats the chemicals topic and retests. Key log: each key signed out and in, any gap reported same day.',
   'Draft an induction outline with timings and agreement headings covering scope, price, access, liability, notice and complaints, plus a key-log template.',
   'Outline covers chemicals, lifting, keys and privacy, timings add up to the stated hours, and the agreement has at least six headings.'),
  ('Launch and growth plan', 'Create', 4,
   'Start with a few reliable clients, price for profit and keep records. Growth that outruns capacity damages quality, so add a client only when hours, staff and cash allow, and review the numbers every month before deciding on one change.',
   ['Define target clients and area.', 'Set weekly hours and capacity.', 'Track hours, income, cost and repeat clients.', 'Review monthly and change one thing.'],
   '3 regular offices, 12 visits each month = 36 visits. Income 36 x 2,919 = 105,084 RUB; costs 36 x 2,189 = 78,804 RUB; gross profit 26,280 RUB before tax and fixed costs. Check: 105,084 - 78,804 = 26,280. Hours: 36 x 4.3 = 154.8 h a month, about 36 h a week over 4.3 weeks, a full working week for one person.',
   'Build a 3-month plan with capacity in hours, income and cost targets, and review dates, adding one new client in month 2.',
   'Plan matches hours to capacity, shows income minus cost for each month, and sets review dates with one change to test.')],
 quiz=[
  ('What is the difference between cleaning and disinfecting?', 'Cleaning removes dirt; disinfecting kills germs and needs a clean surface and contact time, so cleaning always comes first when both are needed.'),
  ('Why never mix bleach with other products?', 'It can release toxic gas that burns the lungs, so use one product at a time, rinse between products and ventilate the room.'),
  ('How much concentrate for 10 L at 1:40?', 'About 244 mL, because 10 000 mL divided by 41 parts is 244 mL, topped up with about 9.76 L of water.'),
  ('What is contact time?', 'The time a disinfectant must stay wet on a surface, stated on the label, before wiping so that germs are actually killed.'),
  ('Why colour-code cloths?', 'To prevent cross-contamination, so a cloth used in a toilet is never used on a desk or in a kitchen area.'),
  ('Why add 15 percent to a job time estimate?', 'For set-up, breaks and travel, which are real working time that the client pays for through the price.'),
  ('What goes in a quote?', 'Scope, frequency, price and exclusions, written down so that both sides know what a visit includes and what costs extra.'),
  ('A checklist of 40 has 3 fails. Pass rate?', '92.5 percent, because 37 passes divided by 40 items is 0.925, which is below a 95 percent target.'),
  ('Can you clean a biohazard area untrained?', 'No; it needs qualified authorisation, special equipment and waste rules, so refuse the job and refer the client onward.'),
  ('Why keep a key log?', 'To protect client property and show who had access, so any loss can be traced and reported on the same day.')],
 rubric=[
  ('Safety', 'Unsafe mixing or no PPE note.', 'Safe-use table complete.', 'Also trains staff with a test.'),
  ('Timing and price', 'Over 5 percent off.', 'Within 5 percent with exclusions.', 'Also models margin by client.'),
  ('Method', 'No cross-contamination plan.', 'Colour code and order of work.', 'Also adapts for special surfaces.'),
  ('Quality', 'No checklist.', 'Checklist and scoring.', 'Also trends fails over time.'),
  ('Business', 'No agreement.', 'Agreement and capacity plan.', 'Also costs growth scenarios.')],
 ladder=[
  'L1 Basic: Remember basic hygiene and that chemicals must not be mixed.',
  'L2 Awareness: Describe cleaning levels and the safety duties for staff.',
  'L3 Foundation: Clean a room to a checklist using safe methods.',
  'L4 Practitioner: Scope, quote and run a small contract with safety and quality records.',
  'L5 Specialist: Analyse cost and quality across clients and design specialised services.',
  'L6 Advanced: Design training, audit and contract systems for a team.',
  'L7 Super expert: Create standards and lead a multi-site cleaning company (needs years of practice).'],
 jobs=[('Cleaner', 'Cleans homes and offices to a checklist.'), ('Team leader', 'Runs a crew and checks quality.'), ('Cleaning supervisor', 'Plans rotas, supplies and inspections.'), ('Small business owner', 'Wins clients, quotes and manages the service.'), ('Facilities assistant', 'Coordinates cleaning for a building.')],
 next='Related generic courses: Facilities Management, Occupational Health and Safety, Small Business Bookkeeping.')

C15 = dict(
 id='RU-15', title='Education (Teaching Practice and Multilingual Digital Delivery)', level='L4 Practitioner',
 summary='Plan, teach and assess lessons with clear outcomes, and deliver them online in more than one language: accessible materials, simple tools, feedback and safe handling of learner data.',
 outcomes=[
  ('Understand', 'Explain how learning outcomes, activities and assessment line up.'),
  ('Apply', 'Write a lesson plan with timed activities, checks for understanding and materials.'),
  ('Analyse', 'Compare learner results to find gaps and adjust teaching.'),
  ('Evaluate', 'Judge a digital lesson for accessibility, language clarity and learner safety.'),
  ('Create', 'Build a short multilingual online module with a rubric and a feedback plan.')],
 task='Design and teach a 45-minute lesson, then adapt it as a short online module in two languages with an assessment and rubric.',
 condition='Desk exercise plus a short peer teaching slot; 6 hours; any common presentation and quiz tools.',
 standard='Outcomes measurable, timings add up, every question maps to an outcome, text readable in both languages, and at least 90 percent of rubric points.',
 who='New teachers and tutors, trainers in companies, community educators and people moving lessons online.',
 req='Knowledge of one subject and the ability to write clearly in at least one language; a second language is needed for the multilingual part.',
 safety='Teaching children and handling learner data is regulated. Licensing or qualification for formal teaching, child-safeguarding duties, background checks, data protection and accessibility duties are set by the relevant federal rules and the competent authority. This course covers practice, not a licence to teach in a school. Check with the competent Russian authority and a local adviser. Never record or share learners images or data without proper permission, and report child-safety concerns through the proper channel.',
 evidence='Evidence: a lesson plan, a rubric, a two-language online module, a question bank mapped to outcomes and a feedback and data-handling note.',
 modules=[
  ('Outcomes that can be tested', 'Understand', 3,
   'Start with what learners will do at the end. Good outcomes use action verbs and can be checked. An outcome states the verb, the condition and the pass mark, so a colleague could mark the same work and reach the same result.',
   ['Write outcomes with verbs such as explain, calculate, compare.', 'Avoid vague words such as know or appreciate.', 'Match each outcome to an activity and a check.', 'Limit a lesson to 2 or 3 outcomes.'],
   'Weak: Understand fractions. Strong: By the end learners add two fractions with unlike denominators correctly in 4 of 5 questions in 10 minutes. Check: 4 of 5 is 80 percent, so a learner with 3 of 5 (60 percent) has not yet met it and receives a short extra task.',
   'Rewrite five weak outcomes as testable ones, and for each write the check question and the pass mark that proves it.',
   'Each outcome has a verb, a condition and a standard, and a colleague marking the same work reaches the same pass or fail for all five.'),
  ('Planning a lesson', 'Apply', 4,
   'A plan sets the time, steps, materials and checks. Leave room for questions. Write the plan so that another teacher could run it, and rehearse the timing aloud once, because new teachers usually run over in the teaching step.',
   ['Use a simple shape: start, teach, practise, check, close.', 'Time every step and total it.', 'List materials and room set-up.', 'Plan for fast and slow learners.'],
   '45 min lesson: start 5, teach 10, practise 15, check 10, close 5 = 45. Reserve 5 minutes spare by shortening practise to 10 minutes: 5 + 10 + 10 + 10 + 5 = 40, leaving 5 spare. Check: 40 + 5 = 45. If teaching runs 3 minutes over, the spare absorbs it and the close still starts on time.',
   'Write a 45-minute plan with timings that add up, 5 minutes of spare time, two outcomes, a materials list and a note on what fast and slow learners do.',
   'Total with spare equals 45, each step maps to an outcome, and the plan lists materials and a task for early finishers.'),
  ('Explaining and questioning', 'Apply', 3,
   'Short, clear explanations plus good questions keep learners thinking. Plan two or three key questions in advance, because questions invented on the spot tend to be closed and test memory only. Mix recall, application and reasoning questions.',
   ['Explain with an example before a rule.', 'Ask open questions and wait 3 to 5 seconds.', 'Check understanding with quick tasks, not just Is that clear?', 'Correct errors kindly and specifically.'],
   'Class of 24: ask a quick question to all, 5 answer aloud, 24 answer on mini boards. You see 24 answers instead of 5, which is 100 percent coverage. Check: 5 of 24 is 21 percent coverage by voice alone. If 6 mini boards show a wrong answer, 18 of 24 are right, which is 75 percent, and you reteach before moving on.',
   'Prepare 8 checking questions for one outcome, two at recall, three at application and three at reasoning level, each with a model answer and a likely wrong answer.',
   'Questions test the outcome at different levels; all 8 have model answers, the levels are labelled, and at least 6 would show a misunderstanding if answered wrongly.'),
  ('Assessment and feedback', 'Evaluate', 4,
   'Assessment shows who has learned and what to teach next. Feedback must be timely and specific. Mark against the rubric, not against other learners, and return feedback while the work is still fresh so that learners can use it in the next task.',
   ['Use a rubric with clear levels.', 'Mix quick checks and a final task.', 'Give feedback with one strength and one next step.', 'Keep scores private.'],
   'Quiz of 10 questions, class of 24: mean 7.1. Q4 correct for 9 of 24 (37.5 percent). Check: 9 / 24 = 0.375 = 37.5 percent. Total marks 24 x 7.1 = 170.4, so the mean is 71 percent; a question near 37.5 percent stands out against that. Reteach Q4 topic next lesson; do not change the others.',
   'Analyse a sample set of results for a class of 20 with 8 questions and write a reteach plan, finding the weakest question, its percent correct and the likely cause.',
   'Plan targets the weakest item with evidence, gives the percent correct to one decimal place, and names one reteach activity of at most 10 minutes.'),
  ('Inclusion and learners needs', 'Evaluate', 3,
   'Learners differ in language, ability and background. Plan so all can take part. Small changes made at planning time cost little, while adjustments after a learner is excluded cost trust. Ask learners privately what helps, and offer the option to everyone.',
   ['Use plain language and short sentences.', 'Offer more than one way to show learning.', 'Provide large print or readable fonts where needed.', 'Ask the school or the competent authority how support needs are handled.'],
   'Text at 14 pt, 1.5 line spacing, contrast ratio over 4.5:1. A glossary of 10 key words given in two languages before the lesson. Check: 10 words x 2 languages = 20 entries, about 10 minutes to write at 30 seconds each.',
   'Adapt one lesson for three different learner needs, such as low reading level, hearing difficulty and a second-language learner, changing materials, timing and the way answers are given.',
   'Adaptations are practical and respectful, each need has at least two concrete changes, and the learning outcome stays the same for all learners.'),
  ('Multilingual digital delivery', 'Create', 4,
   'An online module in two languages needs clear structure, consistent terms and careful translation, not machine output alone. Write the source text in short sentences first, since plain wording translates better and costs less to review. Test the module on one reader of each language before release.',
   ['Keep short chunks: 5 to 8 minutes per unit.', 'Use the same term for the same idea in both languages.', 'Have a second reader check the translation.', 'Provide captions and text alternatives for media.'],
   'Module: 6 units of 6 minutes = 36 minutes, 2 languages. Translation of 1,200 words reviewed in 2 hours; 14 terms in the glossary. Captions for 12 minutes of video. Check: 6 x 6 = 36 minutes. Review rate 1,200 words / 2 h = 600 words per hour. Captions at 3 minutes of work per video minute need 12 x 3 = 36 minutes per language, so 72 minutes for two languages.',
   'Build a 3-unit module in two languages with a glossary, each unit of 5 to 8 minutes, a glossary of at least 10 terms, and captions or text alternatives for every media item.',
   'Terms consistent and every media item has captions or text; a second reader signs off both languages, and no unit exceeds 8 minutes.'),
  ('Online tools, privacy and safety', 'Evaluate', 3,
   'Tools must be easy, accessible and safe. Learner data is private. Pick the simplest tool that does the job, and ask whether each piece of data is needed to teach. If it is not needed, do not collect it, and decide in advance when it will be deleted.',
   ['Choose tools that work on low bandwidth and basic phones.', 'Collect only the data you need.', 'Get permission before recording or sharing learner work.', 'Follow child-safeguarding duties and report concerns correctly.'],
   'Class of 30 with 6 learners on slow connections: provide downloadable 2 MB files and a text version. Attendance data kept for 1 term, then deleted per the rules. Check: 30 - 6 = 24 learners can stream, and 6 of 30 is 20 percent who need the files. A 2 MB file downloads in about 16 seconds at 1 Mbit/s (2 x 8 / 1).',
   'Write a tool and privacy checklist for your module with at least 10 items covering bandwidth, device, permission, data kept, deletion date and who to tell about a safety concern.',
   'Checklist covers access, data, permission and reporting; each item can be answered yes or no, a deletion date is set, and the reporting route is named.'),
  ('Teach, review and improve', 'Create', 4,
   'Teach it, gather evidence and improve. A short cycle repeated often builds skill. Keep the change small enough that you can tell what caused any difference, and record the result in the teaching log with the date, the group size and the pass rate.',
   ['Teach to peers and collect feedback against the rubric.', 'Review results against outcomes.', 'Change one thing and test again.', 'Keep a short teaching log.'],
   'Pilot with 12 learners: 9 met the standard = 75 percent. Target 80 percent. Change: add a worked example; re-test with 12 learners. Check: 9 / 12 = 75 percent; 80 percent of 12 is 9.6, so 10 learners must pass to hit target, one more than now.',
   'Teach a 10-minute segment to a peer and complete a review scored against the rubric, recording the pass rate and one change for the next attempt.',
   'Review names evidence and one change, gives the pass rate as a percent, compares it with the target and sets a date to re-test.')],
 quiz=[
  ('What makes an outcome testable?', 'An action verb, a condition and a standard, such as adding two fractions correctly in 4 of 5 questions within 10 minutes.'),
  ('How should a 45-minute lesson be timed?', 'Steps add up to 45 minutes with a small spare, for example 40 minutes of planned steps plus 5 minutes of buffer.'),
  ('Why wait 3 to 5 seconds after a question?', 'It gives learners time to think and form an answer, so more learners take part and answers show deeper reasoning.'),
  ('What does a rubric do?', 'It shows levels of quality so marking and feedback are consistent, and learners can see what the next level looks like.'),
  ('Q4 was right for 9 of 24. What percent?', '37.5 percent, because 9 divided by 24 is 0.375, so it is the item to reteach.'),
  ('Why check translation with a second reader?', 'To catch meaning errors and keep terms consistent that a single translator may miss, especially for technical terms.'),
  ('What minimum text contrast is a common guide?', 'About 4.5:1 between text and background, which keeps normal text readable for most learners including those with weaker eyesight.'),
  ('Should you share a learner photo without permission?', 'No; ask for permission first, keep it in writing and share only what is needed for the stated purpose.'),
  ('Who sets teaching qualification rules?', 'The relevant federal rules and the competent authority, so check the current rules before you teach for pay or with children.'),
  ('What should you do with a child-safety concern?', 'Report it through the proper channel straight away and do not investigate alone, promise secrecy or confront anyone.')],
 rubric=[
  ('Outcomes', 'Vague verbs.', 'Testable outcomes.', 'Also sequenced across lessons.'),
  ('Plan', 'Timings wrong.', 'Timings add up and map to outcomes.', 'Also differentiates for needs.'),
  ('Assessment', 'Questions not mapped.', 'Mapped with a rubric.', 'Also uses results to reteach.'),
  ('Multilingual delivery', 'Terms inconsistent.', 'Consistent terms, captions provided.', 'Also tested with real learners.'),
  ('Safety and privacy', 'Ignored.', 'Checklist complete.', 'Also trains others.')],
 ladder=[
  'L1 Basic: Remember that a lesson needs a goal and a check.',
  'L2 Awareness: Describe how teaching, assessment and safeguarding fit together.',
  'L3 Foundation: Teach a short, planned segment to a small group.',
  'L4 Practitioner: Plan, teach, assess and deliver a short bilingual online module.',
  'L5 Specialist: Analyse learner data and design courses for a subject or age group.',
  'L6 Advanced: Design curricula, train teachers and evaluate programmes.',
  'L7 Super expert: Create learning systems and standards across institutions (needs years of practice).'],
 jobs=[('Tutor', 'Teaches individuals or small groups in a subject.'), ('Teaching assistant', 'Supports a lead teacher and learners.'), ('Corporate trainer', 'Designs and delivers workplace training.'), ('Online course author', 'Builds digital modules in one or more languages.'), ('Learning support coordinator', 'Plans help for learners with additional needs.')],
 next='Related generic courses: Instructional Design, Language Translation, Child Development Basics.')

C16 = dict(
 id='RU-16', title='Photography and Videography', level='L4 Practitioner',
 summary='Plan, shoot, edit, deliver and price photo and video work: exposure, composition, light, sound, file handling, consent and client agreements.',
 outcomes=[
  ('Understand', 'Explain exposure, depth of field and frame rate and how each changes an image.'),
  ('Apply', 'Set exposure and compose shots for portraits, products and short video scenes.'),
  ('Analyse', 'Compare shots and edits and identify why one communicates better.'),
  ('Evaluate', 'Judge a shoot against a brief and check technical quality.'),
  ('Create', 'Build a shot list, edit workflow, client agreement and price quote for a small job.')],
 task='Plan and price a half-day product and portrait shoot with a short video clip, covering settings, shot list, edit time, file backup and a client agreement.',
 condition='Desk exercise with sample brief, rate table and spreadsheet; 4 hours; shooting practice is encouraged but not required for assessment.',
 standard='Settings reasoned for each shot type, edit time and price correct to 5 percent, backup plan with 3 copies, consent and usage terms stated, and at least 90 percent of rubric points.',
 who='Beginners turning a hobby into paid work, small shop owners making their own content and assistants to working photographers.',
 req='Access to any camera or phone is helpful; basic arithmetic.',
 safety='Photography involves law and safety. Image rights, consent, privacy, work in public and private places, copyright and use of drones are set by the relevant federal rules and the competent authority; drone flying may need registration and permission. Do not photograph people where privacy is expected or children without proper consent. Check with the competent Russian authority and a local adviser. Use safe practice with lights, cables, heights and vehicles.',
 evidence='Evidence: a brief, a shot list, exposure notes, an edit log, a backup record, a client agreement and a quote.',
 modules=[
  ('Light and exposure', 'Understand', 4,
   'A photograph is light captured on a sensor. Aperture, shutter speed and ISO balance exposure and decide look. Changing one control changes the others, so decide first what matters most in the scene: sharp action, a blurred background or low noise, and set the rest to match.',
   ['Aperture controls light and depth of field.', 'Shutter speed controls light and motion blur.', 'ISO raises brightness but adds noise.', 'One stop up or down doubles or halves the light.'],
   'Handheld at 50 mm: use at least 1/50 s to avoid shake. Moving to f/2.8 from f/5.6 is 2 stops more light, so shutter can go from 1/50 to 1/200 s at the same exposure. Check: 2 stops = 2 x 2 = 4 times the light, and 1/50 to 1/200 is 4 times faster. Raising ISO from 400 to 1600 is also 2 stops, at the cost of more noise.',
   'Set exposure for three scenes: bright outdoor, indoor window light, low light, writing aperture, shutter speed and ISO for each, and one stop change that keeps the same exposure.',
   'Each setting is reasoned and avoids shake; each scene has a one-line reason, a shutter at or above 1 over the focal length, and a stated trade-off for ISO.'),
  ('Composition and framing', 'Apply', 3,
   'Composition guides the eye. Simple rules help until you know when to break them. Look at the whole frame before pressing the button: check the background, the edges and the horizon, because these are cheap to fix on location and costly to fix in editing.',
   ['Use thirds, leading lines and clear backgrounds.', 'Leave space for the subject to look or move into.', 'Vary distance: wide, medium, close.', 'Check edges and horizons.'],
   'Shot list for a portrait: 1 wide, 3 medium, 3 close, 2 detail = 9 frames, 3 variations each = 27 images, from which 10 are delivered. Check: 1 + 3 + 3 + 2 = 9 frames, and 9 x 3 = 27. Delivering 10 of 27 keeps 37 percent of images, so the cull is strict and the client sees only the best.',
   'Make a 10-shot list for a product and for a portrait, naming distance, angle, background and purpose for each shot, and mark which three shots would be the hero images.',
   'Shots vary in distance and each has a purpose; both lists have 10 shots, all three distances appear, and the purpose of each shot is one clear sentence.'),
  ('Working with people', 'Apply', 3,
   'People look best when comfortable. Clear directions and consent protect everyone. Talk during the shoot, show a few results on the screen and keep sessions short. A relaxed subject gives better pictures, and a person who understood the use agreed to is less likely to complain later.',
   ['Explain the plan and ask for consent in writing.', 'Give simple directions.', 'Respect privacy and cultural sensitivity.', 'Take extra care with children and ask for guardian consent.'],
   'Shoot of 12 people: 12 signed release forms, 11 agree to web use, 1 refuses; that person is excluded from the web gallery. Check: 11 + 1 = 12. The web gallery uses 11 people, which is 91.7 percent of the group; the refusal is recorded and the files stay off every public channel.',
   'Write a one-page consent and release form with plain wording, a line for each use such as web, print and advertising, a duration, a withdrawal route and a guardian line for under-18s.',
   'Form states use, duration and withdrawal; each use is a separate yes or no tick, the form fits one page, and a guardian signature is required for anyone under 18.'),
  ('Video basics and sound', 'Apply', 4,
   'Video adds motion and sound. Poor sound ruins good pictures. Viewers forgive a slightly soft picture but not hiss, echo or a voice that is hard to hear. Check sound with headphones before you record, and fix problems at the source.',
   ['Choose frame rate: 25 fps standard, 50 fps for slow motion.', 'Set shutter near double the frame rate.', 'Place the microphone close to the speaker.', 'Record 10 seconds of room tone.'],
   'Clip at 25 fps: shutter 1/50. Interview 10 min at 100 MB per minute video = 1 GB; with a 4 GB card you can record 4 interviews. Check: 10 x 100 = 1,000 MB = 1 GB, and 4 / 1 = 4. Add 10 seconds of room tone per clip, which is about 17 MB (10 / 60 x 100), a small cost for easier editing.',
   'Plan a 60-second video with scene list and sound plan, listing 6 scenes with lengths in seconds that add up to 60, the frame rate, shutter, microphone position and the room tone take.',
   'Frame rate, shutter and microphone choices are reasoned; scene lengths total 60 seconds, shutter is about double the frame rate, and the microphone is placed close to the speaker.'),
  ('Editing and delivery', 'Create', 4,
   'Editing selects, corrects and tells the story. Keep originals untouched. Work in a fixed order: cull, correct, crop, export, and save each step under a new name. A clear order makes edit time predictable and stops you from over-processing images.',
   ['Cull to the best frames.', 'Correct exposure, colour and crop gently.', 'Cut video to the story and balance sound.', 'Export in the formats and sizes agreed.'],
   '300 raw images: cull to 60 (20 percent) in 40 minutes; edit 60 x 2 min = 120 min; export 20 min. Total 3 h. Check: 40 + 120 + 20 = 180 min = 3 h. Video 1 minute: 2 h edit, so the whole job needs 5 h, which at 700 RUB/h is 3,500 RUB of edit time.',
   'Estimate edit time for a half-day shoot with 400 images, a cull rate of 20 percent, 2 minutes per kept image, 25 minutes of export and a 1-minute video.',
   'Estimate within 5 percent of the model answer, with each stage (cull, edit, export, video) shown as its own line and added to a total in hours.'),
  ('Files, backup and organisation', 'Apply', 3,
   'Lost files lose clients. Use the 3-2-1 idea: 3 copies, 2 kinds of media, 1 off-site. Back up on the day of the shoot before cards are cleared, and test one restore each month. A backup you have never restored is only a hope.',
   ['Name files by date and job.', 'Copy cards before reformatting.', 'Verify copies.', 'Keep a job log and delete only after delivery and an agreed time.'],
   'Half-day shoot: 300 raw files of 30 MB = 9 GB, plus 2 GB video = 11 GB. Three copies need 33 GB; a 1 TB drive holds about 90 such jobs. Check: 300 x 30 MB = 9,000 MB = 9 GB, 9 + 2 = 11 GB, 11 x 3 = 33 GB. A 1 TB drive is 1,000 GB, and 1,000 / 11 = 90.9, so about 90 jobs for one copy of each.',
   'Write a backup plan with copy count and checks for an 11 GB job, naming each copy, its media type and location, the day it is made, and how you verify it opens.',
   'Plan has 3 copies, 2 media types and 1 off-site; the space needed is calculated as 33 GB, a verification step is listed, and a delete date is set after delivery.'),
  ('Rights, law and safety', 'Evaluate', 3,
   'Copyright and image rights decide who can use what. Some places and flights need permission. Put the rules in writing before the shoot: who owns the files, what the client may do, for how long, and what extra use costs. Clear terms prevent the most common disputes in this trade.',
   ['State who owns the copyright and what the client may use.', 'Ask the competent authority about image rights and drones.', 'Do not use music or others work without permission.', 'Keep cables, stands and locations safe.'],
   'Agreement grants web and print use for 24 months, not resale. Extra use costs 30 percent of the original fee: 6,000 RUB x 0.30 = 1,800 RUB. Check: 6,000 x 0.3 = 1,800. A client who adds poster use pays 1,800 RUB extra, so the total is 6,000 + 1,800 = 7,800 RUB.',
   'Write a usage clause and a site safety list. The clause names owner, permitted uses, duration, territory and extra-use price; the safety list has at least 8 items on cables, stands, heights, crowds and drones.',
   'Clause states owner, uses, duration and extra use; the extra-use price is calculated correctly, nothing is promised that the competent authority has not allowed, and each safety item can be checked on site.'),
  ('Quote, client and business plan', 'Create', 4,
   'Price time and risk, not only the shoot. Include planning, edit and admin. Most beginners price only the hours with the camera in hand and lose money on editing and messages. Track real hours for each job for three months and adjust the minimum fee to match.',
   ['Count shoot, travel, edit, admin and equipment wear.', 'Set an hourly target and a minimum job fee.', 'State what is included, the number of images and revisions.', 'Follow up for feedback.'],
   'Shoot 4 h + travel 1 h + edit 3 h + admin 1 h = 9 h. At 700 RUB/h = 6,300 RUB; equipment wear 400 RUB; total 6,700 RUB for 20 images and 1 video. Check: 4 + 1 + 3 + 1 = 9 h, 9 x 700 = 6,300, and 6,300 + 400 = 6,700. Per delivered item that is 6,700 / 21 = 319 RUB.',
   'Write a quote and agreement for the half-day job showing each hour line, equipment wear, number of images, number of revisions and a payment date.',
   'Quote total correct to 5 percent and includes scope and revisions; the 9 hours are shown, usage terms are stated, and payment and cancellation terms are in the agreement.')],
 quiz=[
  ('What are the three exposure controls?', 'Aperture, shutter speed and ISO; together they set brightness, motion blur, depth of field and noise.'),
  ('What is a stop?', 'A doubling or halving of light, such as moving from f/5.6 to f/4 or from 1/100 s to 1/50 s.'),
  ('Why use 1/50 s at 50 mm handheld?', 'To limit camera shake; the minimum is about 1 over the focal length, so a longer lens needs a faster shutter or a support.'),
  ('What shutter fits 25 fps video?', 'About 1/50 s, which is double the frame rate and gives natural-looking motion blur.'),
  ('What is the 3-2-1 backup idea?', '3 copies, 2 media types, 1 off-site, so one fire, theft or drive failure cannot remove every copy of the work.'),
  ('Why get a signed release?', 'It shows the person agreed to the use, for how long and for which purpose, and it protects both sides if there is a dispute.'),
  ('Who owns copyright by default?', 'Check the rules; state ownership and licence in the agreement so there is no doubt about who may use the files and how.'),
  ('Edit time for 60 images at 2 min each?', '120 minutes, because 60 images times 2 minutes each is 120, which is 2 hours of editing before export.'),
  ('Can you fly a drone anywhere?', 'No; registration and permission may be needed from the competent authority. Never fly over crowds or private property without it, and check the current rules before every flight.'),
  ('Why record room tone?', 'To fill gaps and match sound in editing, because every room has its own background hum and silence cut in would sound unnatural.')],
 rubric=[
  ('Technical', 'Exposure not reasoned.', 'Settings reasoned for each case.', 'Also compares creative alternatives.'),
  ('Planning', 'No shot list.', 'Shot list and sound plan.', 'Also contingency for weather.'),
  ('Files', 'Single copy.', '3-2-1 backup.', 'Also checksums and logs.'),
  ('Legal', 'No consent or usage terms.', 'Consent and usage clause.', 'Also covers drone and location rules.'),
  ('Pricing', 'Time missing.', 'All time counted, within 5 percent.', 'Also tests profit per hour.')],
 ladder=[
  'L1 Basic: Remember what makes a clear picture: light, focus and framing.',
  'L2 Awareness: Describe exposure, consent and copyright basics.',
  'L3 Foundation: Take well-exposed, well-framed photos and a simple video clip.',
  'L4 Practitioner: Plan, shoot, edit, deliver and price a small job with consent and backup.',
  'L5 Specialist: Analyse and lead a style or niche such as products or events.',
  'L6 Advanced: Design a studio workflow, team and licensing model.',
  'L7 Super expert: Create a signature body of work and direct large productions (needs years of practice).'],
 jobs=[('Photographer', 'Shoots portraits, events or products for clients.'), ('Video shooter', 'Records and edits short videos.'), ('Photo editor', 'Selects and corrects images.'), ('Product content creator', 'Makes images and clips for online shops.'), ('Studio assistant', 'Sets up lights, manages files and supports shoots.')],
 next='Related generic courses: Digital Marketing, Graphic Design, Small Business Bookkeeping.')

